{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C54"],
      "claim": "Verapamil, a close structural analog sharing the dimethoxyphenethylamine and basic amine, has an absolute oral bioavailability of 22.0% in normal subjects, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Valbenazine, which shares the dimethoxytetrahydroisoquinoline core, has an absolute oral bioavailability of approximately 49% in humans, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Noscapine, with a dimethoxyaromatic and fused ring system, has an absolute oral bioavailability of 30% in healthy volunteers, supporting F >= 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is structurally similar to verapamil (F ~20-24%, borderline) and valbenazine (F=49%, clearly above threshold). Most verapamil records are at or above 20%, and the more scaffold-similar valbenazine is well above. The mixed physicochemical prior is outweighed by transferable experimental evidence from close analogs, supporting F >= 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "Verapamil values are borderline around the 20% threshold, with some records slightly below.",
    "The query's lactam and fused tetrahydroisoquinoline may alter first-pass metabolism relative to verapamil.",
    "Low neutral fraction (0.02) due to basic pKa may limit passive absorption, but no experimental permeability data are available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

